package rings;public class Access<T> extends CircularQueue<T>{protected Access(T[] storage){super(storage);}public <U extends T>void put(U value){super.put(value);}public T get(){return super.get();}}
class CircularQueue<T>{private final T[] storage;private int read,write,count;CircularQueue(T[] array){storage=array;}<U extends T>void put(U x){if(count==storage.length){System.out.println("Мест нет");return;}storage[write]=x;write=(write+1)%storage.length;count++;}T get(){if(count==0){System.out.println("Данных нет");return null;}T value=storage[read];read=(read+1)%storage.length;count--;return value;}}
